import { Component, OnInit } from '@angular/core';
import { ReactiveFormsModule, UntypedFormBuilder, UntypedFormGroup, Validators } from '@angular/forms';
import { CandidatureService } from 'src/app/services/candidature.service';
import { CommonModule } from '@angular/common';
import * as pdfMake from 'pdfmake/build/pdfmake';
import * as pdfFonts from 'pdfmake/build/vfs_fonts';
import { TDocumentDefinitions, Content, StyleDictionary } from 'pdfmake/interfaces';


(pdfMake as any).vfs = pdfFonts.vfs;



@Component({
  selector: 'app-contact',
  templateUrl: './contact.component.html',
  styleUrls: ['./contact.component.scss'],
  standalone: true,
  imports: [ReactiveFormsModule, CommonModule] // ✅ Import ReactiveFormsModule
})
export class ContactComponent implements OnInit {
  contactForm!: UntypedFormGroup;
  errorMessage: string = '';
  successMessage: string = '';
  cvFile: File | null = null;
  specialites = ['Développement', 'DevVR', 'JeuxVidéo'];
  chartData: { name: string; value: number }[] = [];



  constructor(private formBuilder: UntypedFormBuilder, private candidatureService: CandidatureService) {}



  ngOnInit(): void {

    this.contactForm = this.formBuilder.group({
      name: ['', [Validators.required]],
      email: ['', [Validators.required, Validators.email]],
      dateDeNaissance: ['', [Validators.required]],
      specialite: ['', [Validators.required]],


    });

  }


  generatePDF() {
    const logoBase64 = 'data:image/png;base64,';
    const currentDate = new Date().toLocaleDateString();
    const formValues = this.contactForm.value;
    const documentDefinition: TDocumentDefinitions = {
      pageSize: 'A4',
      pageMargins: [40, 60, 40, 60],

      header: {
        columns: [
          {
            image: logoBase64,
            width: 50
          },
          {
            text: 'Candidate Registration Receipt',
            alignment: 'center',
            fontSize: 20,
            bold: true,
            margin: [10, 15, 0, 0]
          },
          {
            text: currentDate,
            alignment: 'right',
            margin: [0, 20, 10, 0],
            fontSize: 10,
            italics: true
          }
        ]
      },

      footer(currentPage, pageCount) {
        return {
          text: `Page ${currentPage} of ${pageCount}`,
          alignment: 'center',
          fontSize: 9,
          margin: [0, 10, 0, 0]
        };
      },

      content: [
        {
          text: `Hello ${formValues.name},`,
          style: 'greeting'
        },
        {
          text: 'Thank you for submitting your application!',
          margin: [0, 0, 0, 10]
        },
        {
          text: 'We will contact you soon by email regarding your acceptance status.',
          italics: true,
          margin: [0, 0, 0, 20]
        },
        {
          text: 'Candidate Information',
          style: 'sectionTitle'
        },
        {
          table: {
            widths: ['30%', '70%'],
            body: [
              ['Name:', formValues.name],
              ['Email:', formValues.email],
              ['Date of Birth:', formValues.dateDeNaissance],
              ['Specialty:', formValues.specialite || 'N/A'],
            ]
          },
          layout: 'lightHorizontalLines',
          margin: [0, 10, 0, 20]
        },
        {
          text: 'We wish you the best of luck!',
          style: 'closingMessage'
        },
        {
          text: '— Coding Factory Team',
          alignment: 'right',
          margin: [0, 20, 0, 0],
          italics: true
        }
      ],

      styles: {
        greeting: {
          fontSize: 16,
          bold: true,
          margin: [0, 10, 0, 5]
        },
        sectionTitle: {
          fontSize: 14,
          bold: true,
          decoration: 'underline',
          margin: [0, 20, 0, 10]
        },
        closingMessage: {
          fontSize: 12,
          margin: [0, 10, 0, 5],
          bold: true
        },
      }
    };

    pdfMake.createPdf(documentDefinition).download('candidature-receipt.pdf');
  }




  onFileSelected(event: any) {
    if (event.target.files.length > 0) {
      this.cvFile = event.target.files[0];
    } else {
      this.cvFile = null;
    }
  }

  sendMsg(): void {
    this.contactForm.markAllAsTouched();
    this.contactForm.updateValueAndValidity();

    if (this.contactForm.invalid || !this.cvFile) {
      this.errorMessage = 'Please fill all the required fields and upload a CV.';
      return;
    }

    const formData = new FormData() as FormData;

    formData.append('nom', this.contactForm.get('name')?.value);
    formData.append('email', this.contactForm.get('email')?.value);
    formData.append('dateDeNaissance', this.contactForm.get('dateDeNaissance')?.value);
    formData.append('specialite', this.contactForm.get('specialite')?.value);
    formData.append('cv', this.cvFile); // Attach the file

    this.candidatureService.submitCandidature(formData).subscribe({
      next: () => {


        this.successMessage = 'Your application has been submitted successfully!';
        this.generatePDF();
        this.errorMessage = '';
        this.contactForm.reset();
      },
      error: () => {
        this.errorMessage = 'Submission failed. Please try again.';
        this.successMessage = '';
      }
    });
  }


}
